    public Map<String,Object> switchModel(long sessionId,long user,String key,long version,long modelId){return idem.run("user:"+user+":model:"+sessionId,key,Map.of("version",version,"modelId",modelId),()->{PcRecord session=access.resource(PcTable.SESSION,sessionId,user,true,true);store.version(session,version);if(!session.getState().equals("ACTIVE"))throw new PcException(409,"PC_SESSION_READ_ONLY","历史会话不能变更模型，请新建当前绑定会话");if(store.mapper.activeTasks(null,sessionId,null,null)>0)throw PcException.conflict("活跃轮次结束后才能切换模型");sessions.model(modelId,session.getWorkspaceId(),user,false);Map<String,Object> p=store.data(session);p.put("modelId",String.valueOf(modelId));store.save(PcTable.SESSION,session,p);return sessions.detail(sessionId,user);});}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> setupWechat(long user,String key,long workspace){return idem.run("user:"+user+":wechat-setup:"+workspace,key,Map.of("workspaceId",workspace),()->{access.admin(workspace,user);PcRecord r=store.insert(PcTable.WECHAT_BINDING,workspace,user,null,null,null,"WECHAT","LOGIN_REQUIRED",null,Map.of("dailyBudget",100000,"dailyUsed",0,"dailyTurnUsed",0,"queueSize",0,"senderMasked","未绑定","policy",wechatPolicy(Map.of())));Map<String,Object> task=sessions.control(user,workspace,onlineRunner(workspace),null,"WECHAT_SETUP",Map.of("configId",String.valueOf(r.getId()),"configVersion",r.getVersion()));Map<String,Object> v=store.view(r);v.put("taskId",task.get("id"));return v;});}
    public static Map<String,Object> wechatPolicy(Map<String,Object> input){for(String key:input.keySet())if(!Set.of("dailyTurnLimit","singleTurnTokenBudget","commandAllowlist","mcpAllowlist").contains(key))throw PcException.invalid("未知微信策略字段");long turns=input.containsKey("dailyTurnLimit")?PcJson.number(input,"dailyTurnLimit"):50,tokens=input.containsKey("singleTurnTokenBudget")?PcJson.number(input,"singleTurnTokenBudget"):64000;if(turns<1||turns>10000||tokens<1||tokens>1000000)throw PcException.invalid("微信轮次数或单轮Token上限非法");Map<String,Object> result=new LinkedHashMap<>();result.put("dailyTurnLimit",turns);result.put("singleTurnTokenBudget",tokens);for(String field:List.of("commandAllowlist","mcpAllowlist")){Object raw=input.getOrDefault(field,List.of());if(!(raw instanceof List<?> list)||list.size()>100)throw PcException.invalid("微信允许名单须为最多100项字符串");Set<String> values=new LinkedHashSet<>();for(Object item:list){if(!(item instanceof String value)||value.isBlank()||value.length()>(field.equals("commandAllowlist")?8192:256)||value.indexOf('\n')>=0||value.indexOf('\r')>=0||PcSecretPolicy.contains(value))throw PcException.invalid("微信允许名单含非法命令或凭证");if(field.equals("mcpAllowlist")&&!value.matches("[A-Za-z0-9._-]+"))throw PcException.invalid("微信MCP允许名单仅登记服务器名");values.add(value);}result.put(field,List.copyOf(values));}return result;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> saveWechatPolicy(long user,long id,long version,String key,Map<String,Object> input){return idem.run("user:"+user+":wechat-policy:"+id,key,Map.of("version",version,"input",input),()->{PcRecord r=access.resource(PcTable.WECHAT_BINDING,id,user,false,true);access.admin(r.getWorkspaceId(),user);access.workspace(r.getWorkspaceId(),user,true);store.version(r,version);if(store.mapper.activeTasks(r.getWorkspaceId(),null,null,null)>0)throw PcException.conflict("活跃任务结束后才能修改微信策略");Map<String,Object> p=store.data(r);p.put("policy",wechatPolicy(input));p.put("configurationVersion",r.getVersion()+1);p.remove("channelVersion");store.save(PcTable.WECHAT_BINDING,r,p);evidence.audit(r.getWorkspaceId(),user,null,r.getSessionId(),"WECHAT_POLICY","UPDATED",Map.of("bindingId",id,"version",r.getVersion()));return projection("wechat",r);});}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> bindWechat(long user,long id,long version,String key,Map<String,Object> input){return idem.run("user:"+user+":wechat-bind:"+id,key,input,()->{PcRecord r=access.resource(PcTable.WECHAT_BINDING,id,user,false,true);access.admin(r.getWorkspaceId(),user);access.workspace(r.getWorkspaceId(),user,true);store.version(r,version);long target=PcJson.number(input,"userId");access.role(r.getWorkspaceId(),target);String sender=PcJson.text(input,"sender");if(sender.isBlank()||sender.length()>256)throw PcException.invalid("微信sender非法");long budget=PcJson.number(input,"dailyBudget");if(budget<1||budget>1000000)throw PcException.invalid("微信预算非法");String hash=PcJson.digest(sender);for(PcRecord existing:store.mapper.list(PcTable.WECHAT_BINDING,null,null,null,null))if(!existing.getId().equals(r.getId())&&hash.equals(store.data(existing).get("senderHash")))throw PcException.conflict("此sender已绑定其他工作区");Map<String,Object> p=store.data(r);p.remove("channelVersion");p.remove("configurationVersion");p.put("senderHash",hash);p.put("boundUserId",String.valueOf(target));p.put("boundUserName",String.valueOf(target));if(input.get("modelId")!=null){long model=PcJson.number(input,"modelId");sessions.model(model,r.getWorkspaceId(),target,false);p.put("modelId",String.valueOf(model));}if(input.get("policy")!=null)p.put("policy",wechatPolicy(PcJson.object(input,"policy")));p.put("dailyBudget",budget);p.put("senderMasked",sender.substring(0,Math.min(2,sender.length()))+"***");r.setState("BOUND");store.save(PcTable.WECHAT_BINDING,r,p);evidence.audit(r.getWorkspaceId(),user,null,null,"WECHAT_BIND","ACCEPTED",Map.of("bindingId",id,"senderHash",hash));return store.view(r);});}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> evaluation(long user,String key,Map<String,Object> input){return idem.run("user:"+user+":eval",key,input,()->{long workspace=PcJson.number(input,"workspaceId");access.admin(workspace,user);if(!"IMPORT_REPORT".equals(PcJson.text(input,"action")))throw PcException.deny("正式评测仍暂停，仅允许准备和导入报告");PcRecord artifact=access.resource(PcTable.ARTIFACT,PcJson.number(input,"artifactId"),user,false,false);if(!Objects.equals(artifact.getWorkspaceId(),workspace))throw PcException.deny("评测报告不属于当前工作区");Map<String,Object> p=new LinkedHashMap<>();p.put("name",store.data(artifact).getOrDefault("fileName","导入报告"));p.put("paused",properties.isFormalEvaluationPaused());p.put("publishable",false);p.put("formalScores",null);p.put("reportArtifactId",String.valueOf(artifact.getId()));p.put("sourceDigest",artifact.getContentHash());p.put("missingEvidence",List.of("独立verifier与冻结配方证据须核对"));p.put("gaps",List.of("原项目D5/E3/E4尚未正式完成"));PcRecord r=store.insert(PcTable.EVALUATION_RUN,workspace,user,null,null,null,"REPORT_IMPORT","IMPORTED_UNVERIFIED",null,p);evidence.audit(workspace,user,null,null,"EVAL_IMPORT","UNVERIFIED",Map.of("evaluationId",r.getId()));return store.view(r);});}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> harness(long user,String key,Map<String,Object> input){return idem.run("user:"+user+":harness",key,input,()->{long sessionId=PcJson.number(input,"sessionId");PcRecord session=access.resource(PcTable.SESSION,sessionId,user,true,false);String mode=PcJson.text(input,"mode");if(!Set.of("QUICK","NORMAL","INLINE").contains(mode))throw PcException.invalid("Harness模式非法");PcRecord r=store.insert(PcTable.HARNESS_RUN,session.getWorkspaceId(),user,sessionId,sessionId,session.getRunnerId(),"HARNESS","ENQUEUED",null,input);Map<String,Object> task=sessions.control(user,session.getWorkspaceId(),session.getRunnerId(),sessionId,"HARNESS_"+mode,Map.of("harnessId",String.valueOf(r.getId()),"mode",mode));Map<String,Object> v=store.view(r);v.put("taskId",task.get("id"));return v;});}
    private Map<String,Object> secretGrant(String ref,String baseUrl){ManagedSecretService.Resolved resolved=secrets.resolve("AI",ref);return Map.of("apiKey",resolved.value(),"secretRef",ref,"secretVersion",resolved.metadata().activeVersion(),"baseUrl",baseUrl,"expiresAt",store.clock.instant().plusSeconds(properties.getLeaseSeconds()).toString());}
    public long definition(PcRecord r){return store.data(r).get("configurationVersion") instanceof Number n?n.longValue():r.getVersion();}
    public Map<String,Object> configuration(PcRecord r){Map<String,Object> p=Set.of("SKILL","SKILLS").contains(r.getKind())?skillView(r):store.view(r);p.put("version",definition(r));return p;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> reloadSkills(long user,String key,long workspace){access.admin(workspace,user);return idem.run("user:"+user+":skill-reload",key,Map.of("workspaceId",workspace),()->{access.workspace(workspace,user,true);return queueSkills(user,workspace);});}

    /** 名称关闭保存在工作区真相中，不能被新增、导入或单层回退绕过。原配置及来源记录不改写。 */
    @Transactional("paicliTransactionManager")
    public Map<String,Object> skillName(long user,long workspace,String key,String name,boolean enabled){
        access.admin(workspace,user);
        return idem.run("user:"+user+":skill-name:"+workspace,key,Map.of("name",name,"enabled",enabled),()->{
            PcRecord owner=access.workspace(workspace,user,true);
            if(store.mapper.list(PcTable.SKILL_CONFIG,workspace,null,null,null).stream().noneMatch(r->name.equals(PcJson.text(store.data(r),"name"))&&!r.getState().equals("REVOKED_IMPORT")))throw PcException.invalid("没有登记该Skill名称");
            changeSkillName(owner,name,enabled);
            evidence.audit(workspace,user,null,null,"SKILL_NAME",enabled?"ENABLED":"DISABLED",Map.of("name",name,"skillStateVersion",skillStateVersion(store,workspace)));
            return queueSkills(user,workspace);
        });
    }
    private Map<String,Object> skillAction(long id,long user,String key,long version,Map<String,Object> input){
        PcRecord selected=access.resource(PcTable.SKILL_CONFIG,id,user,false,false);access.admin(selected.getWorkspaceId(),user);
        return idem.run("user:"+user+":skills:"+id+":action",key,Map.of("version",version,"input",input),()->{
            PcRecord owner=access.workspace(selected.getWorkspaceId(),user,true);PcRecord row=access.resource(PcTable.SKILL_CONFIG,id,user,false,true);store.version(row,version);
            if(!PcJson.text(input,"action").isBlank()&&!PcJson.text(input,"action").equals("RELOAD"))throw PcException.invalid("Skill配置动作须为RELOAD");
            if(input.containsKey("enabled")){
                if(!(input.get("enabled") instanceof Boolean enabled))throw PcException.invalid("Skill启用开关须为布尔值");
                Map<String,Object> data=store.data(row);if(enabled&&!approvedSkill(data))throw PcException.deny("Skill须先核对并登记当前全文及信任摘要");
                data.put("enabled",enabled);data.put("effective",false);data.put("configurationVersion",definition(row)+1);store.save(PcTable.SKILL_CONFIG,row,data);
                if(enabled)changeSkillName(owner,PcJson.text(data,"name"),true);
                evidence.audit(row.getWorkspaceId(),user,null,null,"SKILL_CONFIG",enabled?"ENABLED":"DISABLED",Map.of("configId",id,"version",row.getVersion()));
            }
            return queueSkills(user,row.getWorkspaceId());
        });
    }
    private void changeSkillName(PcRecord workspace,String name,boolean enabled){
        Map<String,Object> data=store.data(workspace);Set<String> disabled=disabledSkillNames(data);boolean changed=enabled?disabled.remove(name):disabled.add(name);
        if(changed){data.put("disabledSkillNames",disabled.stream().sorted().toList());data.put("skillStateVersion",skillStateVersion(store,workspace.getId())+1);store.save(PcTable.WORKSPACE,workspace,data);}
    }
    private Map<String,Object> queueSkills(long user,long workspace){
        Map<String,Object> args=new LinkedHashMap<>();args.put("configs",skillConfigurations(workspace).stream().map(v->{Map<String,Object> value=new LinkedHashMap<>(v);value.put("version",definition(store.require(PcTable.SKILL_CONFIG,PcJson.number(v,"id"),false)));return value;}).toList());args.put("skillStateVersion",skillStateVersion(store,workspace));
        return sessions.control(user,workspace,onlineRunner(workspace),null,"SKILLS_RELOAD",args);
    }
    private static Set<String> disabledSkillNames(Map<String,Object> workspace){Set<String> names=new LinkedHashSet<>();if(workspace.get("disabledSkillNames") instanceof List<?> values)for(Object value:values)if(value instanceof String text)names.add(text);return names;}
    private static long skillStateVersion(PcStore store,long workspace){Object value=store.data(store.require(PcTable.WORKSPACE,workspace,false)).get("skillStateVersion");return value instanceof Number n?n.longValue():0;}
    private static int skillLayer(Map<String,Object> data){return switch(PcJson.text(data,"scope").toUpperCase(Locale.ROOT)){case "BUILTIN"->0;case "USER","PERSONAL"->1;default->2;};}
    private static boolean approvedSkill(Map<String,Object> data){String content=PcJson.text(data,"content"),sha=PcJson.text(data,"sha256");return Boolean.TRUE.equals(data.get("manifestApproved"))&&!content.isBlank()&&sha.equals(PcJson.text(data,"trustHash"))&&sha.equals(PcJson.digest(content));}
    private static Map<String,PcRecord> effectiveSkillRows(PcStore store,long workspace){
        Set<String> disabled=disabledSkillNames(store.data(store.require(PcTable.WORKSPACE,workspace,false)));Map<String,PcRecord> winners=new HashMap<>();
        store.mapper.list(PcTable.SKILL_CONFIG,workspace,null,null,null).stream().sorted(Comparator.comparingInt(r->skillLayer(store.data(r)))).forEach(r->{Map<String,Object> data=store.data(r);String name=PcJson.text(data,"name");if(!disabled.contains(name)&&Boolean.TRUE.equals(data.get("enabled"))&&approvedSkill(data)&&!r.getState().equals("REVOKED_IMPORT"))winners.put(name,r);});
        return winners;
    }
    /** load_skill与重载共用同一层级/名称开关规则；消费前须仍匹配Runner实际加载版本。 */
    public static String approvedSkillFingerprint(PcStore store,long workspace,String name){
        store.require(PcTable.WORKSPACE,workspace,true);PcRecord row=effectiveSkillRows(store,workspace).get(name);
        if(row==null)throw PcException.conflict("Skill名称已停用、未批准或未登记，不能加载旧上下文正文");Map<String,Object> data=store.data(row);long version=data.get("configurationVersion") instanceof Number n?n.longValue():row.getVersion();
        return store.json.hash(Map.of("id",String.valueOf(row.getId()),"version",String.valueOf(version),"sha256",PcJson.text(data,"sha256")));
    }
    public List<Map<String,Object>> skillConfigurations(long workspace){
        Set<String> disabled=disabledSkillNames(store.data(store.require(PcTable.WORKSPACE,workspace,false)));List<PcRecord> rows=store.mapper.list(PcTable.SKILL_CONFIG,workspace,null,null,null);
        Map<String,Long> winners=new HashMap<>();effectiveSkillRows(store,workspace).forEach((name,row)->winners.put(name,row.getId()));
        return rows.stream().map(r->{Map<String,Object> data=store.data(r),view=store.view(r);String name=PcJson.text(data,"name");boolean configured=Boolean.TRUE.equals(data.get("enabled")),nameDisabled=disabled.contains(name);view.put("configuredEnabled",configured);view.put("nameDisabled",nameDisabled);view.put("enabled",configured&&!nameDisabled&&!r.getState().equals("REVOKED_IMPORT"));view.put("effective",Objects.equals(r.getId(),winners.get(name)));return view;}).toList();
    }
    private Map<String,Object> skillView(PcRecord row){return skillConfigurations(row.getWorkspaceId()).stream().filter(v->String.valueOf(row.getId()).equals(v.get("id"))).findFirst().orElseThrow();}
    public List<Map<String,Object>> skillsForTask(PcRecord task){
        Map<String,Object> args=PcJson.text(store.data(task),"operation").equals("SKILLS_RELOAD")?PcJson.object(store.data(task),"arguments"):Map.of();
        if(args.get("configs") instanceof List<?> configs&&args.containsKey("skillStateVersion")){validateSkillSnapshot(store,task);return configs.stream().map(v->{Map<String,Object> value=new LinkedHashMap<>();((Map<?,?>)v).forEach((k,item)->value.put(String.valueOf(k),item));return value;}).toList();}
        return skillConfigurations(task.getWorkspaceId()).stream().map(v->{Map<String,Object> value=new LinkedHashMap<>(v);value.put("version",definition(store.require(PcTable.SKILL_CONFIG,PcJson.number(v,"id"),false)));return value;}).toList();
    }
    public static void validateSkillSnapshot(PcStore store,PcRecord task){
        Map<String,Object> args=PcJson.object(store.data(task),"arguments");if(!args.containsKey("skillStateVersion"))return;
        PcRecord workspace=store.require(PcTable.WORKSPACE,task.getWorkspaceId(),true);Object currentState=store.data(workspace).get("skillStateVersion");long stateVersion=currentState instanceof Number n?n.longValue():0;
        if(PcJson.number(args,"skillStateVersion")!=stateVersion)throw PcException.conflict("Skill名称开关已改变，请重新发起重载");
        Map<Long,Long> frozen=new HashMap<>();if(!(args.get("configs") instanceof List<?> configs))throw PcException.invalid("Skill重载缺少冻结配置");for(Object value:configs){Map<String,Object> config=new LinkedHashMap<>();((Map<?,?>)value).forEach((k,v)->config.put(String.valueOf(k),v));frozen.put(PcJson.number(config,"id"),PcJson.number(config,"version"));}
        List<PcRecord> current=store.mapper.list(PcTable.SKILL_CONFIG,task.getWorkspaceId(),null,null,null);if(current.size()!=frozen.size())throw PcException.conflict("Skill登记集合已改变，请重新发起重载");
        for(PcRecord row:current){Map<String,Object> data=store.data(row);long version=data.get("configurationVersion") instanceof Number n?n.longValue():row.getVersion();if(!Objects.equals(frozen.get(row.getId()),version))throw PcException.conflict("Skill批准版本已改变，请重新发起重载");}
    }
